// Сгенерировано tools/build-base-media.mts: описания карточек справочника (TMDb), доля 14 из 16 по id
// (src/lib/shard.ts) — подгружается, когда раскрывают «Сюжет» (src/api, getPlot). Не править руками.
export const blurbs: Record<string, string> = {
 "f-wd1388653": "Когда из морских глубин поднялись легионы чудовищ, известных как кайдзю, началась война, которой суждено было забрать миллионы жизней и свести «человеческие ресурсы» почти к нулю всего за несколько лет. Чтобы сражаться с пришельцами, было создано специальное оружие: огромные роботы, названные егерями, они управлялись одновременно двумя пилотами, чьи сознания соединены с помощью нейронной связи. Но даже егеря оказываются почти бессильны перед лицом безжалостных кайдзю. На грани поражения у защитников человечества нет выбора, кроме как обратиться к двум весьма сомнительным героям – никому не нужному бывшему пилоту и неопытному стажеру – которые объединились, чтобы повести в бой некогда легендарного, но сейчас устаревшего егеря. Вместе они оказываются единственной надеждой человечества, последним препятствием перед надвигающимся апокалипсисом.",
 "f-wd21647114": "Наш мир – не единственный из существующих. Заклятые враги Роланд Дискейн (Идрис Эльба), последний из ордена стрелков, и Уолтер О’Дим (Мэттью МаКонахи), известный также как Человек в черном, ведут извечную борьбу. На кону – мифическая Темная Башня, последний оплот и надежда вселенной, без которой мир будет повержен в полный хаос и разрушение. Силам добра и зла суждено столкнуться в последней схватке, ведь Роланд Дискейн – единственный, кому под силу остановить Человека в черном, прежде чем тот разрушит Темную Башню. Основано на знаменитом бестселлере мастера ужасов и фэнтези Стивена Кинга.",
 "f-wd13619743": "Миньонов Стюарта, Кевина и Боба нанимает Скарлетт Оверкилл, суперзлодейка, которая вместе со своим мужем-изобретателем Хербом замышляет захватить мир.",
 "f-wd192686": "В поисках сакрального знания группа ученых отправляется в самые темные и неизведанные чертоги вселенной. Именно там, в отдаленных мирах, находясь на пределе своих умственных и физических возможностей, им предстоит вступить в безжалостную схватку за будущее всего человечества.",
 "f-wd111677117": "История происхождения ясновидящей, известной как мадам Паутина, чьи экстрасенсорные способности позволяют ей видеть в мире пауков.",
 "f-wd16795448": "История о четырёх молодых астронавтах, которые отважились на авантюрное путешествие в параллельное измерение для исследования аномальной волны космической энергии. Вернувшись из путешествия, они обнаружили у себя суперспособности, которые навсегда изменили их жизни…",
 "f-wd29580929": "Джейк Салли, Нейтири и их дети переживают смерть Нетейама. Противостояние с корпорацией RDA обостряется, и теперь семье предстоит столкнуться с враждебным племенем На`ви во главе с Варанг.",
 "f-wd115932544": "Исследуя заброшенную космическую станцию, группа космических колонизаторов сталкивается лицом к лицу с самой ужасающей формой жизни во Вселенной.",
 "f-wd122741016": "После смерти сына Гамнета Агнес остаётся в Стратфорде с детьми, а Уильям Шекспир возвращается в Лондон, чтобы написать пьесу, которая станет одним из его величайших творений.",
 "f-wd213053": "Цивилизация планеты Криптон стоит на грани гибели. Ученый Джор-Эл, чтобы спасти своему ребенку жизнь, отправляет его на Землю. Маленький мальчик вырастает и открывает в себе неземные возможности. Он — Супермен!  Огромная сила и способность летать помогают ему в борьбе с любыми проявлениями зла. И когда коварный злодей Лекс Лютор строит зловещие планы, угрожающие всему человечеству, только Супермен может помешать ему…",
 "f-wd467582": "После того как в американском поселке в Саудовской Аравии произошел теракт, туда направляется группа лучших агентов ФБР для проведения расследования, на которое у них есть одна неделя. Но вскоре агенты выясняют, что методы ведения расследования, эффективные в западном мире, не дают ожидаемых результатов на востоке. Кроме того, перед ними встает новая угроза — ведь для террористов нет более заманчивой цели, чем группа следователей, направленная для их поимки.",
 "f-wd2196619": "СССР. 1984 год. Финал советской эпохи. Провинция. После дискотеки пропадает дочь секретаря райкома партии. Свидетелей нет. Виновные не обнаружены. В этот же вечер в доме на окраине города происходит жестокое убийство. Виновный — хозяин дома. Оба расследования поручены капитану милиции Журову…",
 "f-wd842770": "Томас Крео ищет Древо Жизни, сок которого, как говорят легенды, дарует вечную жизнь. Томасу же необходимо спасти свою смертельно больную жену Изабель.",
 "f-wd732022": "Действие картины происходит в не слишком отдалённом будущем. Главный герой внезапно просыпается в 2092 году дряхлым стариком и понимает, что он является 120-летним последним смертным на планете, доживающим свой век среди счастливых бессмертных людей.",
 "f-wd751805": "Он живёт в мире вечной ночи, но эта темнота заполнена звуками и запахами, её можно попробовать на вкус и потрогать руками. Адвокат Мэтт Мердок слеп, но остальные органы чувств у него работают, как у супермэна.Днём Мердок защищает униженных и оскорблённых в зале суда, а ночью превращается в сорвиголову в маске, восстанавливая справедливость на улицах города самыми радикальными методами.",
 "f-wd1130395": "1943 год, Великая Отечественная война. Подросток Флёра, откопав карабин среди обрывков колючей проволоки, ржавых пулемётных лент и простреленных касок, отправляется в лес к партизанам.",
 "f-wd73896894": "Молодой ветеран войны возвращается домой с посттравматическим синдромом и пытается найти свое место в мире. Несмотря на поддержку возлюбленной, его затягивает мир наркотиков и криминала.",
 "f-wd849656": "Её рождения боялись веками. С начала эры в своих одиноких кельях отшельники переписывали слова страшного пророчества. В глубине времен звезды предсказали младенцу страшную судьбу: она должна стать невестой самого Дьявола. И в конце тысячелетия Сатана восстанет из ада, чтобы вступить с несчастной в страшный союз. Если это случится, на земле наступит царство Зла и человечество навсегда погрузится во тьму. Ужасное пророчество, в которое боялись поверить, сбылось. Князь тьмы вырвался из заточения в поисках своей невесты. Время повернуло вспять, отсчитывая мгновения до рокового финала. Но предсказатели не учли одного - того, кто осмелился встать на пути у всесильного Люцифера, чтобы в одиночку остановить Апокалипсис.",
 "f-wd280400": "Матильда - очень необычная девочка. Ну посудите сами - умножать в голове огромные числа, двигать взглядом предметы и делать еще много чего сверхъестественного - это что, по-вашему, нормально? Но ее родители равнодушны к ней - их не только не поражают способности Матильды, им даже не интересно, как живет их дочь.",
 "f-wd919649": "После гибели Смауга за сокровища Одинокой горы сходятся пять воинств: гномы, эльфы, люди, орки и варги. Древние союзы трещат под давлением жадности и страха, а попытки сохранить мир тонут в нарастающем хаосе. Когда битва становится неизбежной, на первый план выходят честь, верность и личный выбор. Исход сражения определяет будущее этих земель.",
 "f-wd50650165": "В ночь Хеллоуина клоун-маньяк терроризирует трёх девушек, а также всех, кто попадается ему на пути.",
 "f-wd547189": "После смерти родителей молодой счетовод Уильям Блэйк в надежде найти работу приезжает на Дикий Запад, где по злой воле случая за его голову назначается награда в 500 долларов. Раненого в грудь возле сердца, его выхаживает индеец, которого много лет возили по городам Америки и Англии в качестве живого экспоната. Он принял этого юношу в очках за поэта Уильяма Блэйка, чьи стихи запали в сердце «дикаря», и стал его ангелом-хранителем. А опекаемый, лишившись очков, сам вдруг стал стрелять без промаха, увеличивая стоимость своей головы, оставляя за собой след из трупов лиц, охочих до награды, и приближаясь к тому «месту, откуда приходят и куда возвращаются все духи».",
 "f-wd55621609": "Сью Энн – одна из тех приятных женщин, которые внушают доверие с первого взгляда. Более того, она принадлежит к числу уникальных \"стариков\", не мешающих молодежи веселиться. Даже наоборот, Сью покупает старшеклассникам алкоголь и охотно предоставляет для их пьяных тусовок подвал своего дома. В этом доме нет никаких ограничений, кроме одного: никогда не заходи в её комнату.",
 "f-wd327332": "Пёс-призрак — наёмный убийца, подчинивший свою жизнь кодексу чести самурая. Он безоговорочно служит своему хозяину-мафиози, однажды спасшему его жизнь, но когда мафиозная семья предаёт Пса-призрака, кодекс обращается против них.",
 "f-wd96377121": "За много лет до того, как стать тираническим президентом Панема, 18-летний Кориолан Сноу — последняя надежда своего угасающего рода, некогда гордой семьи, потерявшей благородство в послевоенном Капитолии. С приближением 10-х ежегодных Голодных игр молодой Сноу встревожен, когда его назначают наставником Люси Грей Бэрд, девушки-трибуна из бедного Дистрикта 12. Но после того, как Люси Грей привлекает внимание всего Панема, дерзко спев во время церемонии жатвы, Сноу думает, что сможет переломить ситуацию в свою пользу. Объединив свои инстинкты шоумена и политическую смекалку, Сноу и Люси Грей попадают в водоворот событий в борьбе за выживание. В конечном итоге они выяснят, кто из них певчая птица, а кто змея...",
 "f-wd17182571": "Фильм расскажет историю близнецов Реджи и Ронни Крэй, культовых фигур преступного мира Великобритании 1960-х. Братья возглавляли самую влиятельную бандитскую группировку Ист-Энда. В их послужном списке: вооружённые грабежи, рэкет, поджоги, покушения, убийства и собственный ночной клуб, куда доезжали даже голливудские знаменитости. Среди их жертв — криминальные авторитеты Джек МакВитти и Джордж Корнелл.",
 "f-wd113005257": "«… Жили-были два бродяги… Нет… Три… Да нет же — четыре… Но были и другие, разные… Я их знал. Долго. Годы. Потом что-то случилось, и они исчезли. На протяжении многих лет я о них ничего не слышал. Жили-были… и их было четверо… Я был погружён в жизнь и беды новые. Но последние годы ко мне являлось смутное чувство, что округ меня ходят, ходят, ходят… По ночам слышались голоса, обрывки сложных вопросов, слова на чужих языках, стоны, вой миллионов голосов… Неизъяснимое волнение охватило меня… Этой ночью хляби небесные разверзлись… И… понеслось…»",
 "f-wd65154506": "История матча за звание чемпиона мира, который прошел на Филиппинах в 1978 году, между действующим чемпионом Анатолием Карповым и претендентом на этот титул - гроссмейстером Виктором Корчным, несколько лет назад эмигрировавшим из СССР.",
 "f-wd41483": "В разгар гражданской войны таинственный стрелок скитается по просторам Дикого Запада. У него нет ни дома, ни друзей, ни компаньонов, пока он не встречает двоих незнакомцев, таких же безжалостных и циничных. По воле судьбы трое мужчин вынуждены объединить свои усилия в поисках украденного золота. Но совместная работа — не самое подходящее занятие для таких отъявленных бандитов, как они. Компаньоны вскоре понимают, что в их дерзком и опасном путешествии по разорённой войной стране самое важное — никому не доверять и держать пистолет наготове, если хочешь остаться в живых.",
 "f-wd218894": "Из Европы отправляется в Новый Свет корабль с нашим героем Джоном Смитом. Экипаж, как объясняет капитан, плывет навстречу приключениям, успеху, богатству. Но сам капитан намерен найти там нечто вполне определенное - золото. А живут в Америке индейцы, и рассказ пойдет о благородной принцессе Покахонтас - красивой дочери вождя индейцев. У нее есть друг - веселый и любопытный енот, который очень любит проказничать. Однажды, во время прогулки, Покахонтас замечает большой корабль с белокожими незнакомцами на борту. \"Эти Белые Люди принесут много бед нашему народу!\" - предсказывает вождь. Капитан корабля из-за жажды золота начинает войну против мирного индейского народа. Сможет ли Покахонтас предотвратить неизбежную войну и спасти свой народ?...",
 "f-wd270940": "В основе фильма лежит старая басня про цыпленка, который вопил о том, что небеса падают на землю каждый раз, когда ему на голову падал желудь. Вот уже год, как Цыпленок пытается преодолеть позор своей ошибки (про падающие небеса) и жить как ни в чем не бывало.Но — увы! — желающих дружить с неудачником немного, и поэтому в товарищах у него ходят такие же изгои, как и он сам. Но однажды действительно случается несчастье — пора бить тревогу! Но кто поверит Цыпленку, ведь он уже опростоволосился однажды…",
 "f-wd193577": "Тед Крамер, целиком посвятив себя карьере, не замечает того, что происходит в собственной семье. Поэтому от него уходит жена, оставляя незадачливого отца заботиться о шестилетнем сыне.  Теперь Крамер старший должен выступить в непривычной роли: ему предстоит ухаживать за Крамером младшим, проводить с ним больше времени и, наконец, попытаться проникнуть в хрупкий и ранимый мир ребенка. Но в тот момент, когда отец и сын становятся настоящими друзьями, раскаявшаяся мать возвращается. И она хочет забрать мальчика.",
 "f-wd107761": "После того, как таинственная ракета захватывает космические объекты, пилотируемые с орбиты Земли, мировые супердержавы оказываются на грани войны. Их единственная надежда — Джеймс Бонд, который мчится, чтобы остановить настоящего преступника, Эрнста Блофельда, подстрекателя и провокатора мирового масштаба. Агент 007 и японские ниндзя из секретной службы должны найти и остановить его прежде, чем начнётся ядерная война.",
 "f-wd204374": "Американский Юг, на дворе 1960-е годы. Скитер только-только закончила университет и возвращается домой, в сонный городок Джексон, где никогда ничего не происходит. Она мечтает стать писательницей, вырваться в большой мир. Но для приличной девушки с Юга не пристало тешиться столь глупыми иллюзиями, приличной девушке следует выйти замуж и хлопотать по дому.  Мудрая Эйбилин на тридцать лет старше Скитер, она прислуживает в домах белых всю свою жизнь, вынянчила семнадцать детей и давно уже ничего не ждёт от жизни, ибо сердце её разбито после смерти единственного сына.  Минни — самая лучшая стряпуха во всём Джексоне, а ещё она самая дерзкая служанка в городе. Двух чёрных служанок и белую неопытную девушку объединяет одно — обострённое чувство справедливости и желание хоть как-то изменить порядок вещей. Смогут ли эти трое противостоять целому миру? Сумеют ли они выжить в этой борьбе?",
 "f-wd224130": "Четыре астронавта в далёком космосе попали под действие неизвестных лучей и приобрели каждый свою отдельную суперспособность. После возвращения на Землю, четвёрка начинает активно мешать врагам цивилизации, которые усиленно портят жизнь всего прогрессивного человечества.",
 "f-wd286868": "Много-много лет назад. Ной — набожный отец семейства, которого начинают посещать ужасные видения конца света. Поняв, что людей ждет неминуемая гибель, он начинает строить ковчег — гигантский корабль, который должен защитить его семью и его самого от бушующих волн. Однако Ною приходится бороться не только с собственными страхами, но и с вполне осязаемым человеческим злом, ведь люди, прослышавшие о строительстве корабля, тоже захотели спастись. Только вот для них в ковчеге не было места.",
 "f-wd337881": "История самого некомпетентного и недалекого Британского дипломата, которого только можно представить, которого ошибочно принимают за самого знаменитого и опасного шпиона Великобритании, Джонни Инглиша. Из-за этой путаницы герой оказывается вовлеченным в смертельную схватку с авторами очередного дьявольского плана.",
 "f-wd217552": "Фильм рассказывает о неистовом и романтичном прошлом Росомахи, его сложных отношениях с Виктором Кридом и о зловещей программе Оружие Х. При этом Росомаха встречается со многими мутантами, уже знакомыми и новыми, и узнает несколько легенд о мире Людей Икс.",
 "f-wd212041": "Когда-то в Лондоне жил молодой и наивный брадобрей Бенджамин Баркер. Он был женат на прелестной женщине по имени Люси, которая родила ему такую же прелестную дочку. На его беду, прелесть его жены также оценил сластолюбивый судья Терпин — и отправил Бенджамина Баркера на пожизненную каторгу, чтобы без помех овладеть его женой.  Пятнадцать лет спустя Баркер бежал с каторги, под именем Суини Тодда добрался до Лондона — и не нашел у себя дома ни жены, ни дочери. Миссис Ловетт, хозяйка маленькой пекарни этажом ниже, вначале не узнавшая его, рассказала ему его собственную историю. Тодд был уничтожен и поклялся страшно отомстить своим обидчикам — судье Терпину и приставу Бэмфорду, который помогал судье в его недостойных делах. По совету миссис Ловетт, не скрывающей своей привязанности к беглецу, он вернулся к своему прежнему ремеслу — снова стал брадобреем в надежде когда-нибудь заполучить к себе в заведение судью и прикончить его.",
 "f-wd194413": "Эта история двух друзей — летчиков. Их судьбы переплавились в топке Второй мировой войны. Их чувства были опалены языками великой страсти. Огонь стал для них вторым домом.Мир рушился, прошлое скрылось в сумерках пожарищ, и теперь за будущее должен был бороться каждый, на земле и на небе, в дружбе и вражде.",
 "f-wd271006": "1942 год, разгар Сталинградской битвы. Немецкое командование направляет на передовую своего лучшего стрелка, майора Кенига, с особым заданием. Этот опытный и терпеливый профессионал - единственный, кто может попытаться справиться с русским «ангелом смерти» - неуловимым снайпером Василием Зайцевым. Зайцев - легенда и икона для защитников Сталинграда. Каждый день он выносит смертный приговор десяткам захватчиков, попавших в перекрестье его прицела. Между двумя уникальными снайперами начинается смертельная схватка, победителем из которой будет суждено выйти лишь одному...",
 "f-wd108586": "Амбициозная и властная нью-йоркская начальница узнает, что срок ее вида на жительство заканчивается и ей грозит депортация в Канаду. Чтобы не потерять работу, для нее остается один выход — срочно заставить кого-то из своих подчиненных фиктивно на ней жениться...",
 "f-wd159054": "История героя сопротивления полковника Клауса фон Штауффенберга, возглавившего заговор против Гитлера. В 1944 году он попытался взорвать диктатора, пронеся в портфеле бомбу, но все, что ему удалось - только ранить фюрера.",
 "f-wd15046091": "Фильм расскажет о приключениях молодой девушки по имени Элла. Овдовев, отец Эллы женится во второй раз. Стараясь поддержать отца, Элла принимает новую семью — мачеху Леди Тремэйн и ее дочерей Анастасию и Дризеллу в своем доме. Вскоре и отец Эллы трагически погибает, а девушка оказывается один на один с жадными и завистливыми новыми родственниками. Из хозяйки дома она превращается в служанку, испачканную золой, за что и получает прозвище — Золушка.",
 "f-wd104409060": "«Базз Лайтер» расскажет не о персонаже, известном поклонникам основной серии мультфильмов, а о вымышленном космонавте, на основе которого и начали выпускать те самые игрушки.",
 "f-wd648312": "Банда грабителей под руководством Чарли Крокера во всю прыть несется на Мини Куперах по улицам Лос-Анджелеса и даже заныривает в подземку. Банда стремится увезти в безопасное место добычу — сейф, набитый золотом.В Лос-Анджелесе с его чудовищными пробками просто так не поездишь, поэтому банда предварительно позаботилась о «зеленой улице» для себя: на всех светофорах по пути их следования горит только зеленый свет. Для остальных, соответственно, горит красный, что провоцирует грандиознейшую в истории Лос-Анджелеса дорожную пробку.",
 "f-wd901213": "32-летний британец-интеллектуал Чарльз каждый раз очень напрягается, когда на горизонте вырисовывается перспектива женитьбы. Однажды на очередной свадебной церемонии он знакомится с очаровательной американкой Кэрри, и тут его оборонительная стратегия дает роковую трещину.",
 "f-wd637169": "Главный герой мультфильма — странный ученый Флинт Локвуд, который всегда хотел изобрести что-то такое, что сделает его родной городок счастливым. И вот, у него получилось! Еды теперь хватает всем, и она просто падает с неба, создавая новые пейзажи вокруг: можно любоваться закатом с живописных холмов из фруктового желе. Но иногда вкусные осадки в виде фрикаделек могут превратиться в настоящий торнадо из аппетитных, но уже опасных спагетти! Гениальному ученому и его друзьям предстоит исправить положение дел в сытом городке.",
 "f-wd107167": "Поздней ночью радио доносит голос маленького ребенка, который ищет маму. Сотни женщин со всей страны откликаются на этот зов, и только одна из них понимает — отец ребенка и она — предназначены друг для друга, пусть даже между ними сотни миль. И не беда, что она обручена, а ее новый избранник еще не знает о ней. Его единственная и далекая ждет и ищет его, влюбившись с первого звука его голоса.",
 "f-wd206497": "Реальная история игрока в американский футбол команды Baltimore Ravens Майкла Оэра. Оставшийся без крова молодой афроамериканец взят под опеку зажиточной семьёй. Жизнь в новом окружении полностью меняет судьбу замкнутого подростка, помогает реализовать свой потенциал. Поступив в университет штата Миссисипи, он играет в студенческой команде и познаёт скрытую сторону спортивной игры, учится стратегии и тактическому анализу. Знание того, что в игре зачастую именно мозг побеждает мускулы, вскоре поможет попасть Майклу в профессиональную лигу.",
 "f-wd27958298": "История о первом и решающем шаге Уинстона Черчилля на посту премьер-министра Великобритании, получившего власть при чрезвычайных обстоятельствах. Успехи нацистской армии взбудоражили британское сообщество, но вопреки давлению и страху других политиков Черчилль отказывается идти на соглашение с Гитлером.",
 "f-wd643263": "История жизни и любви двух сестер - чувственной Элинор и страстной Марианны, чье счастье и будущее омрачено смертью отца и потерей огромного состояния семьи.",
 "f-wd468484": "Картина повествует о знаменитой высадке в Нормандии, легендарном дне «Д» — 6 июня 1944 года.  Ранним утром того дня армада из 5 тысяч судов армии союзников, сосредоточенных на Британских островах, пересекла Ла-Манш и начала высадку экспедиционных сил на побережье Нормандии. Как для союзников, так и для немцев это был самый долгий день…",
 "f-wd18405": "Проститутка Кабирия, работающая в одном из самых дешевых районов Рима, как и все её подруги вульгарна, грязна, драчлива, остра на язык. Но вопреки своей древней и циничной профессии, она по-детски наивна и добра, с маниакальным упорством надеется найти мужчину своей мечты и стать честной женщиной. Её сердце жаждет любви, но мир жесток…",
 "f-wd253978": "Лето 1963 года. 17-летняя Фрэнсис по прозвищу Бэби, невинная избалованная девушка из обеспеченной семьи, проводит каникулы с родителями в курортном отеле. Она знакомится с Джонни, красивым профессиональным танцором, искушенным в вопросах жизни и любви.Словно околдованная сексуальными ритмами и ничем не сдерживаемыми движениями «грязных танцев» в стиле ритм-энд-блюз, Бэби становится ученицей-партнершей Джонни — и в танцах и в любви.",
 "f-wd270599": "Прошло 2 года после кровавой бойни в Вудсборо. Сидни Прескотт поступила в колледж, уехав прочь от безумных воспоминаний. Но прошлое вновь настигает её: нашумевшая история стала книгой - бестселлером Гэйл Уэзерс, а теперь ещё вышел фильм о тех самых событиях, всколыхнувший новую волну террора. И ужас ожил снова, и снова в каждом встречном видится убийца!",
 "f-wd1305092": "Великая Отечественная война. Молодой солдат Алёша Скворцов совершает подвиг - подбивает два немецких танка. Командование собирается представить его к ордену, но Алёша просит дать ему отпуск, чтобы повидаться с мамой. Путь домой долог и непрост. Алеша помогает безногому инвалиду встретиться с женой, девушке Шуре - добраться до тетки. Даже последнюю ночь отпуска он проводит не под родной крышей, а спасая детей от бомбежки. И у солдата Скворцова остаётся всего несколько минут, чтобы обнять мать и сказать: «Я вернусь!»",
 "f-wd59721": "Человек - наш современник, неожиданно оказывается в Эрмитаже начала 1700 годов, не имея ни малейшего представления о том, как он туда попал. Осматривая залы, он встречает иностранца, в котором угадывает черты известного французского дипломата и путешественника XIX века.Эти двое путешествуют по времени сквозь 300 лет российской истории, произведения искусства и памятники культуры возвращают их во времена Российской империи.Два человека, странник и наш соотечественник, спорят о взаимосвязи России и Европы и становятся свидетелями многих исторических событий: Петр Первый устраивает разнос генералу, Екатерина Великая руководит репетицией пьесы, за обедом сидит последний император России вместе со своей семьей.Это путешествие - воспоминание о том великолепии далекого прошлого, по которому тоскуют те, кто никогда в нем не жил...",
 "f-wd1125687": "Во время тегеранской конференции готовится убийство руководителей держав-противников Германии во Второй Мировой войне - Иосифа Сталина, Франклина Рузвельта и Уинстона Черчилля.  Но основное действие фильма происходит в наши дни. Бывшие непосредственные участники событий - и даже их дети - как бы заново переживают минувшее, но не для всех эти воспоминания заканчиваются благополучно.",
 "f-wd1192171": "Однажды талантливый ученый доктор Сальватор спас жизнь маленькому мальчику, пересадив ему жабры акулы. С этого дня Ихтиандр, так назвал своего приемного сына ученый, мог плавать под водой, как рыба, нырять на любую глубину, но ему было тяжело подолгу находиться на суше… Годы спустя по тихому морскому городу поползли слухи о странном существе, наводящем ужас на всех рыбаков, o «морском дьяволе». В это же самое время в городе появляется молодой человек, который мало общается с людьми и прекрасно плавает. Он знакомится с дочерью бедного ныряльщика за жемчугом, красавицей Гутиэре и без памяти в нее влюбляется…",
 "f-wd2714901": "Полное драматизма киноповествование об интернациональной арктической экспедиции под руководством Умберто Нобиле, о постигшей её катастрофе и спасении большинства участников советскими лётчиками и моряками ледокола \"Красин\". Этот фильм о мужестве и риске, о силе и слабости духа, о цене жизни и смерти, о самом суровом суде — суде совести.",
 "f-wd1059786": "Вернувшись в Алма-Ату, Моро не хочет, чтобы родители знали о его приезде, и в поисках временного пристанища вспоминает о девушке, которую он когда-то любил. Дина рада встрече, но Моро что-то настораживает в ней. Наблюдая за её странными знакомыми, Моро понимает, что Дина стала наркоманкой. Как спасти девушку? Моро увозит её к морю, где Дина начинает выздоравливать. Однако после возвращения в город всё начинается сначала. Моро решает расправиться с поставщиками наркотиков.",
 "f-wd33189": "Он был обречен на гибель, но выжил, чтобы отомстить за истребление своего рода. Последний человек из племени Серых Псов стал могучим воином, называющим себя Волкодав. Избежав смерти в подземных рудниках, Волкодав пускается в путь в сопровождении своего спутника, Нелетучего Мыша. Волкодав одержим желанием покарать Людоеда, уничтожившего деревню Серых Псов.Добравшись до замка заклятого врага, Волкодав жестоко расправляется с Людоедом. Там же он освобождает двух пленников, мудреца Тилорна и рабыню Ниилит. Вместе с ними Волкодав попадает в город Галирад, переживающий смутные времена. Кнес Галирада, стремясь спасти город от разорения, сватает свою дочь Елень за молодого воина Винитара, обещающего защиту Галираду.Юной кнесинке предстоит дальняя дорога в земли будущего мужа. Она просит Волкодава стать ее телохранителем в опасном путешествии. Согласившись служить кнесинке, Волкодав оказывается втянутым в водоворот таинственных событий, проливающих свет на истинную цель поездки...",
 "f-wd4193504": "По одноименной сказке А.Н.Толстого. О приключениях деревянного мальчика Буратино и его друзей - Пьеро, Мальвины и пуделя Артемона, о таинственном золотом ключике, открывающем заветную дверь, о добром папе Карло и злом Карабасе-Барабасе, Дуремаре, коте Базилио и лисе Алисе. Именам главных героев: папы Карло, Буратино, Дуремара, черепахи Тортиллы и других персонажей этого произведения суждено было стать нарицательными — столь велика оказалась популярность этой сказки. Фильм частично снят как игровой и как кукольный мультфильм.",
 "f-wd866673": "Аслан Гугаев, командир отряда чеченских боевиков, отпускает троих пленников. Двух русских солдат сержанта Ивана Ермакова и рядового Кулика - потому что они не контрактники, а призывники. И англичанина Джона Бойла - потому что он должен собрать два миллиона фунтов стерлингов и привезти деньги Гугаеву в качестве выкупа за свою невесту Маргарет. Маргарет остается у Аслана. Так же, как и капитан российской армии Медведев... За отведенные ему два месяца Джон не находит нужную сумму и не находит поддержки у британских властей, зато, вернувшись в Россию, находит Ваню Ермакова, живущего в Тобольске. Джон и Ваня опять едут в Чечню. Чтобы освободить английскую девушку Маргарет и русского капитана Медведева...",
 "f-wd704456": "О восстании рабочих киевского завода «Арсенал» против Центральной Рады Украины в январе 1918 года.",
 "f-wd4080435": "Двадцатый год. Гражданская война близится к завершению. После вторжения Красной Армии в Крым начинается исход всех, кто искал спасения от «окаянных дней» революции. В этом страшном течении оказываются рядом самые разные люди — беззащитная Серафима Корзухина и полковая дама Люська, приват-доцент Голубков и генерал Хлудов.",
 "f-wd3999206": "Жил-был мальчик по прозвищу Дядя Фёдор. Он очень любил животных, но его родители и слышать ничего не хотели о том, чтобы в их квартире завёлся кто-то хвостатый и лохматый. И пришлось Дяде Фёдору со своими новыми приятелями — котом Матроскиным и верным пёсиком Шариком — отправиться в деревню Простоквашино.",
 "f-wd1969508": "Герои фильма расстались на Белорусском вокзале летом 1945-го. Спустя четверть века они встречаются на похоронах боевого товарища. В их душах с новой силой оживает пережитое. Время не властно над их памятью: ветераны сохранили верность фронтовой дружбе, способность жертвовать собой, неистребимую любовь к жизни.",
 "f-wd4306612": "Таксист Петя Говорков репетирует роль Ленского в любительском оперном театре. Старый певец и дирижер Македонский предсказывает ему блестящее будущее. Но премьера спектакля заканчивается провалом из-за того, что накануне Петя поссорился с любимой девушкой.",
 "f-wd194941": "Девочка Оля вечно не слушалась свою бабушку, капризничала и ленилась. Однажды, погнавшись за убежавшим через волшебное зеркало котом Барсиком, Оля попала в сказочное Королевство Кривых Зеркал, где столкнулась со своим собственным отражением - девочкой по имени Яло. Разыскивая кота и его отражение, девочки становятся свидетелями ареста юного зеркальщика Гурда, и решают вызволить мальчика из Башни.",
 "f-wd932464": "Герой фильма как-то отправляется в лес, чтобы жечь уголь. И там, на полянке, ему повстречалась Аленушка, которая пасла своего козленка. Но слуги Кащея Бессмертного похитили девушку прямо на глазах у Васи. В поисках возлюбленной Вася в буквальном смысле проходит сквозь огонь и воду. Но труднее всего устоять перед медными трубами, перед сверкающим сиянием славы…",
 "f-wd1018998": "Фильм рассказывает о зарождении, становлении и развитии советского ракетостроения — от первых пятилеток до создания сверхдальних современных ракет. В фокусе внимания создателей ленты судьба Андрея Башкирцева, главного конструктора, отдавшего жизнь осуществлению великой мечты — освоению Космоса.",
 "f-wd4366111": "Продолжение музыкальной фантазии, любимой не одним поколением зрителей, о необыкновенных, очень опасных и веселых приключениях бременских музыкантов. Эта история о том, как «славный король» силой возвращает дочь во дворец...",
 "f-wd4182801": "В прошлом студент консерватории и хороший флейтист, а в настоящем — муж дочери «большого человека», и сам начальник одного из подразделений Главного управления Леонид Семёнович Филимонов, однажды почувствовал физическое недомогание: прихватило сердце. И это в неполные сорок лет от роду! Сей неприятный случай послужил поводом для знакомства бывшего флейтиста с молоденькой медсестрой из ведомственной поликлиники Лидой. И закрутился бурный роман...",
 "f-wd1245367": "Герой ленты, режиссер-самоучка, энтузиаст нового революционного искусства Искремас («искусство — революционным массам») посвятил свою жизнь театру. Он начал свою деятельность в провинциальном городке, который переходил из рук в руки: красных теснили белые, белых — зеленые.",
 "f-wd3407516": "По фантастической повести Н. В. Гоголя. Жарким августом к царице с гетманской грамотой отправляют в столицу казака. По дороге заводит он знакомство с разгульным запорожцем. На привале новый друг рассказал, что продал душу дьяволу и ждёт расплату. Ночью казак не стал ложиться спать, решил посмотреть, что дальше будет. Как стемнело, на место привала пришёл чёрт, увёл лошадь, а с ней и царскую грамоту. Пришлось гонцу искать пропажу в переполненном нечистой силой лесу. На утро распрощался казак со знакомцем и, уже без остановок, помчался в Петербург.",
 "f-wd4229887": "О рядовом коммунисте Василии Губанове, участнике одной из первых советских строек. Фильм, признанный новаторским, — в нем впервые возник не ходульный, но совершенно жизненный, человеческий образ коммуниста...",
 "f-wd1963018": "По мотивам трилогии А. Н. Островского «Праздничный сон до обеда», «За чем пойдёшь, то и найдешь», «Две собаки дерутся — третья не приставай». Мелкий чиновник Бальзаминов мечтает жениться — и обязательно на богатой. Забавные ситуации, в которых то и дело оказывается герой, пытающийся найти невесту, составляют сюжет одной из популярнейших советских кинолент.",
 "f-wd4427579": "Деревенский паренек Иван Бровкин считался «непутевым», потому председатель колхоза старался держать от него подальше свою дочь Любашу. Захар Силыч попробовал сделать из Ивана шофера. Но Иван подвел своего наставника, утопив в речке колхозный грузовик. Лишь заступничество матери за сына и... повестка в армию помогли избежать серьезных последствий. Не сразу Иван стал умелым воином, но солдатская дружба и взаимовыручка, помощь и внимание командиров помогли ему достичь успехов в службе. А Люба ждала своего возлюбленного и отвергала ухаживания «интеллигентного» бухгалтера. Ефрейтор Иван Бровкин прибыл на побывку уже другим человеком, и Люба теперь не боялась колкостей и злословий со стороны односельчан в адрес своего суженного. Из «непутевого» парня армейская служба превратила Ивана в самостоятельного человека, готового к любым трудностям.",
 "f-wd17031156": "Злая колдунья, очаровав короля и став его женой, пожелала превратить одиннадцать своих пасынков в черных воронов. Однако заклятье ведьмы удалось лишь отчасти: юноши превратились в прекрасных белых лебедей. Их сестра Элиза готова была пожертвовать всем, чтобы ее братья вновь стали людьми. Девушка узнала, что заклятье исчезнет, если сплети им рубашки из жгучей крапивы, что растет на кладбище. Но есть одно условие: ни одного произнесенного слова во время работы, иначе все ее старания и надежды окажутся напрасными...",
 "f-wd261403": "Он — мужчина, профессиональный автогонщик. Она — красивая, умная женщина. У каждого из них есть свое прошлое с привкусом печали. Теперь ОН и ОНА глубоко одиноки, и мир воспоминаний владеет ими больше, чем мир обыденной реальности.  Случайная встреча, неожиданно сильное, волнующее чувство вырвет героев из холодных лап одиночества. Новая близость, хрупкая и неуверенная, не сразу подарит им простое счастье, на тернистом пути, к которому нужно будет найти немало смелых ответов на труднейшие вопросы бытия…",
 "f-wd1114038": "Богатая и красивая женщина не мешает когда-то любимому ею мужчине утопиться. Утопленник перевоплощается в себя, но на этот раз настолько же решительного и волевого, насколько раньше был рохлей и хлюпиком.",
 "f-wd1211971": "Пьер — респектабельный архитектор средних лет. Он расстался со своей красавицей-женой Катрин и живет теперь с очаровательной любовнице Элен. Жизнь удалась? Или дала трещину? Что делать: радоваться или грустить?  Пьер не может понять. Он очень нерешителен. Хотя, увидев его, Вы подумаете: «Вот — настоящий мужчина». Также думала и Элен. Но однажды вечером она сказала: «Я устала тебя любить».",
 "f-wd2611776": "С шести лет Брэд страдает синдромом Туретта. Его симптомы — частые моторные и вокальные тики, которые невозможно подавить. Тем не менее, Брэд бросает вызов всем барьерам и неприятностям, и даже двадцать четыре отказа подряд не останавливают его на пути к своей мечте — стать учителем.",
 "f-wd61664894": "Семейная пара Лиза и Шон вместе с маленьким сыном Джудом переезжает в большой дом, не подозревая о его страшном прошлом. Подозрения возникают, когда Джуд заводит дружбу с необычной фарфоровой куклой по имени Брамс, которая слишком похожа на живую.",
 "f-wd4030858": "Фантастическая история любви художника, живущего в XXI веке и принцессы королевства Парадор, времен правления короля Артура.",
 "f-wd2364089": "Папу маленького мальчика на его глазах похитили инопланетяне, а мама, не поверив рассказанной истории, решила, что муж просто ушел от нее. С тех пор прошло три года, у мамы появился новый сожитель, но парень все еще верил, что настоящий папа вернется. И он вернулся, будучи, правда, уже не таким, как раньше…",
 "f-wd123690382": "Ребека, Крис и их дети Тайлер и Хлоя — вполне обычная семья, справляющаяся со знакомыми многим трудностями. Ребека — трудоголик и строгая мама, из-за неурядиц на работе она всё чаще срывается на дочери, и Крису приходится вставать на сторону Хлои, которая сейчас особенно чувствительна ко всему — недавно она пережила смерть двоих друзей. И именно Хлоя первой начинает замечать в их новом доме присутствие чего-то потустороннего.",
 "f-wd125449414": "Ближайшее будущее. Отчаявшийся отец Бен Ричардс решает принять участие в жестоком реалити-шоу «Бегущий человек», надеясь выиграть деньги для лечения тяжелобольной дочери. Чтобы победить, участники должны выжить, пока в течение 30 дней на них охотится группа убийц.",
 "f-wd24284798": "Цирковой импресарио Марк Медичи назначает бывшую звезду цирка Холта Фэрриера и его детей Милли и Джо опекунами новорождённого слонёнка, чьи невероятно большие уши сразу становятся предметом для постоянных шуток и насмешек коллег Холта по цеху. Внезапно узнав, что Дамбо умеет летать, владелец цирка решает нажиться на необычных способностях слонёнка. К делу подключается энергичный предприниматель Вэндевер, который решает сделать из малыша Дамбо главную звезду своего нового грандиозного развлекательного предприятия «Сказочная страна».",
 "f-wd34779365": "Капитан корабля спустя годы вновь встречает свою любимую женщину, которая вышла замуж за богача, а теперь хочет избавиться от него. Чтобы осуществить это, она просит помощи у того, кто до сих пор испытывает к ней чувства.",
 "f-wd21877685": "Основатели парка Юрского периода решают восстановить его работу, пренебрегая действующим вулканом, который находится в центре острова. Огнедышащий исполин пробуждается и грозит утопить всё в лаве. Клэр Дэринг вынуждена снова обратиться за помощью к дрессировщику Оуэну Грэди, чтобы спасти животных от верной смерти.",
 "f-wd18350210": "Действие фильма начинается в Лондоне, где премьер-министр Великобритании погибает при загадочных обстоятельствах. На похоронах безусловно присутствуют руководители западного мира. Но то, что начиналось как наиболее безопасное событие на земле, превращается в опаснейшее покушение на самых мощных мировых лидеров, что в свою очередь ставит под угрозу будущее всего мира. Только три человека сохраняют надежду на предотвращение катастрофы: президент США, его верный помощник — агент спецслужбы и английский агент МИ-6, который никому не доверяет.",
 "f-wd15079316": "Молодой китобой отправляется в опасное плавание на судне «Эссекс», рассчитывая на удачную охоту и хорошую добычу. Но в открытом океане экипаж сталкивается с гигантским кашалотом, который наносит кораблю сокрушительный удар и оставляет моряков без надежды на быстрое спасение. Оказавшись посреди бескрайнего моря, выжившие начинают долгую борьбу за жизнь, сталкиваясь с голодом, жаждой, штормами и тяжёлыми моральными испытаниями.",
 "f-wd2389686": "Герой выведен по ту сторону добра и зла. Он — таксидермист, больной эпилепсией. Аурой называется обморок, предшествующий внезапному эпилептическому приступу, — миг клинической смерти, отключения сознания, потери идентичности. Не случайно имя героя ни разу не произносится. Не случайно он занимается производством чучел — ни живых, ни мертвых. Одиночка и интроверт, он заводит себя тем, что проворачивает в голове идеальные — бескровные, незаметные — ограбления. До тех пор пока не появляется шанс осуществить задуманное и испытать фатальную разницу между желаемым и действительным. Поехав на охоту, герой нечаянно убивает человека, перепутав его с дичью. Жертвой оказывается криминальный тип, незадолго до гибели подготовивший план налета на инкассатора. Безымянный герой ступает на его место…",
 "f-wd744551": "Полковник в отставке Джон Матрикс — бывший командир спецотряда, участвовавшего в секретных операциях на Ближнем Востоке, СССР и Центральной Америке. Находясь в отличной физической форме и владея знаниями, которые делают его супер-солдатом, полковник в отставке Джон Матрикс живет под другим именем в большом доме со своей дочерью вдали от города.",
 "f-wd1234664": "Отряд британских солдат под командованием сержанта Уэллса отправляется на учения в дикие леса горной Шотландии. Прибыв в лагерь бойцов спецназа, солдаты обнаруживают истекающего кровью капитана Райана и растерзанные останки его подчиненных.",
 "f-wd1146345": "Во второй части отряд «G.I. Joe» вновь объявит вызов группировке «Кобра» и вступит в противостояние с правительством…",
 "f-wd261700": "Планета Марс, 2176 год. На одну из дальних шахтерских станций, на специальном поезде отправляется отряд полиции, чтобы забрать, и доставить в город опасного преступника Уильямса, подозреваемого в убийстве и грабеже. Однако члены отряда еще даже не догадываются о той опасности, которую им приготовил Марс. Ведь отважным полицейским придется столкнуться не столько с людьми, сколько с таинственными и зловещими силами, живущими в самой планете.",
 "f-wd16011764": "Овдовевшую женщину с шестилетним сыном начинает преследовать монстр Бабадук — герой из рассказов-ужасов. Поначалу нервное и странное поведение матери и сына кажется объяснимым для окружающих — без мужской поддержки прожить им сложно. Но вскоре открываются истинные причины, ведь по ночам к ним является Бабадук, чтобы напугать до смерти...",
 "f-wd1583771": "Группа людей оказывается загнанной в ловушку, в лесах Западной Вирджинии, где они вынуждены бороться за свои жизни против группы порочных, и ужасно уродливых каннибалов.",
 "f-wd23759268": "В Ираке солдат Ник Мортон и археолог Дженни Хэлси обнаруживают древнюю гробницу египетской принцессы Ахманет, которая была погребена заживо после попытки обрести сверхъестественную силу. Освободившись спустя тысячи лет, Ахманет начинает возвращать себе могущество и стремится завершить древний ритуал, чтобы призвать бога смерти Сета. Нику предстоит противостоять пробудившейся мумии и силам древнего зла, пока её планы не приведут к катастрофе.",
 "f-wd20649227": "Когда подпольная сделка по продаже оружия феерически летит под откос, целый склад превращается в масштабное поле битвы. Слова закончились, и заговорили стволы. Приз в игре на выживание — кейс с большой суммой денег, но унести его не так просто. Здесь вооружены все, каждый сам за себя, а хаос правит бал.",
 "f-wd3403358": "Невиданная и загадочная древняя Русь, утопающая в красках первозданной природы и старинных праздников. Деревянные города и необъятные просторы, жестокие сражения и щедрые пиры, шумные ярмарки и грандиозные охоты. На фоне всех этих исторических событий и удивительных приключений крепнет настоящая дружба и рождается первая любовь…",
 "f-wd3525931": "В секретной лаборатории ФБР ученые разработали препарат, который позволяет человеку справиться с любой неизлечимой болезнью. Руководство спецслужб предлагает принять это лекарство экс-агенту спецслужб Итану Раннеру, которому врачи объявили смертельный диагноз. Но он должен выполнить еще одно задание, которое, впрочем, может стоить ему жизни. Теперь вокруг Раннера начинают происходить странные вещи. Что это — галлюцинации, побочный эффект от таблеток или мир действительно полон ужаса и кошмара?",
 "f-wd124408825": "Финист Ясный Сокол — самый удалой богатырь Белогорья, самый сильный, самый ловкий и самый красивый. Все остальные богатыри на него равняются, дети хотят быть на него похожими, а девушки — просто заглядываются. Он горделив и самоуверен, и порой даже отказывается от подвигов, если считает их скучными и неинтересными. Но ему просто необходимо оставаться лучшим, чтобы люди продолжали им восхищаться. Чтобы всех удивить, Финист отправится за новыми свершениями в непростое путешествие, которое приведет его в восточные земли, где богатырь поймет простую истину — один в поле не воин.",
 "f-wd27942936": "Финеас Тейлор Барнум всегда мечтал войти в историю, но все его занятия не приносили ему удовольствия. И когда, казалось, весь мир обернулся против него, он решает пойти вслед за своей мечтой. Барнум создаёт завораживающее представление-сенсацию, которое стало рождением мирового шоу-бизнеса.",
 "f-wd3566895": "Дэвид Кларк — мелкий торговец наркотиками. Среди его клиентов — повара и скучающие домохозяйки. Детям он наркотики не продаёт и поэтому считает себя принципиальным человеком. Дэвид действительно хорошо относится к детям, но это не остается безнаказанным — он пытается помочь подросткам, попавшим в беду, и на него нападают хулиганы. Они отбирают у него наркотики и деньги, и Дэвид оказывается в отчаянном положении. Ведь ему нечем расплатиться с поставщиком. Единственный выход — подрядиться на доставку крупной партии наркотиков через границу.",
 "f-wd19587336": "Мистическая история, исследующая тайну строительства Великой китайской стены.",
 "f-wd824389": "В горах после снежной лавины теряются 5 человек. На их поиски отправляется один из лучших альпинистов и горных проводников – Гейб Уокер. Неожиданно он понимает, что его специально заманили в горы для совершенно другого дела.\r Также становится ясно, что Гейб станет нежелательным свидетелем, от которого без раздумья «избавятся». Но свою жизнь он терять так просто не собирается и объявляет безжалостную войну банде вооруженных до зубов боевиков под предводительством международного террориста Эрика Куалена...",
 "f-wd751382": "Сейлор и Лула спасаются от безжалостной команды наемных убийц, нанятых безумной матерью Лулы Мариэттой. В погоню за беглецами вначале пускается дружок Мариэтты, частный детектив Джонни, а когда Джонни возвращается ни с чем, Мариэтта призывает на помощь своего бывшего любовника, гангстера Сантоса…",
 "f-wd261546": "Мир будущего, в котором все письменные издания безжалостно уничтожаются специальным отрядом пожарных-огнеметчиков, а интерес к книгам и их хранение преследуются по закону. Сержант Гай Монтэг слепо выполняет приказы по уничтожению литературы, но встреча с юной Клариссой заставляет его переосмыслить свою жизнь. Он становится инакомыслящим — отщепенцем в тоталитарном обществе, читающем только комиксы.",
 "f-wd47492499": "В Райм-Сити, огромном городе, где рядом с людьми живут Покемоны, внезапно исчезает частный детектив Гарри Гудман. Открывается расследование, однако кажется, что он просто испарился. Своё собственное расследование начинает его сын Тим. На помощь к нему приходит покемон Пикачу, который многие годы был лучшим другом и верным напарником Гарри Гудмана.",
 "f-wd748599": "Франция накануне Второй мировой войны. Авиатора Андре Жюрье, совершившего рекордный перелет, встречают на земле его друг Октав и толпа взбудораженных репортеров, он сообщает радиослушателям, что предпринял эту авантюру из-за любви к женщине, которая, однако, даже не пришла поприветствовать его в аэропорт. Это Кристин. В это время она готовится выйти в свет со своим мужем, который знает о романе жены, но не хочет ее потерять.  Сам он пытается порвать с обожающей его любовницей. Октав признается Андре, что ему также не безразлична Кристин, и заявляет, что тот никогда не получит ее, так как пренебрегает правилами игры в обществе… Чуть позже оба попадают на уик-энд и охоту в загородное поместье де ла Шеснея. Здесь и разыгрывается безжалостная игра, ограниченная жесткими правилами «высшего света». Все, включая слуг, имеют свои маленькие драмы…",
 "f-wd380841": "Комедия о сумасшедшей калифорнийской семейке, в которой — две «мамочки» Ник и Джулс растят двух детей-подростков, появившихся на свет путем искусственного оплодотворения. Пятнадцатилетний Лейзер упрашивает старшую сестру Джони, которой только что исполнилось восемнадцать, помочь ему отыскать их биологического отца. Мальчику очень не хватает настоящего мужского общения. Джони без особого энтузиазма обещает помочь брату.В результате неожиданно обнаружившийся папаша решает приударить за одной из «мамочек», и знакомство деток с родителями, да и знакомство самих родителей, оборачивается чередой нелепых, смешных, а иногда и грустных ситуаций.",
 "f-wd13374569": "Отсидев в тюрьме за преступление, которого он не совершал, автомеханик и уличный гонщик Тоби выходит на свободу, и полон решимости поквитаться с тем, кто его подставил.",
 "f-wd949217": "Три подружки слишком рано узнают о взрослой жизни. Их первой школой стали улицы революционного Петрограда.",
 "f-wd97315487": "Февраль 1942 года, лютые морозы, страшный голод. Не работает водопровод и электричество, транспорт стоит, Ленинград завален снегом и парализован. Молодая женщина Ольга идёт через весь город к своему отцу. Она только что похоронила мужа и уверена, что скоро тоже умрёт от голода. Она хочет в последний раз увидеть своего отца и проститься с ним.",
 "f-wd1337415": "В недалеком будущем команда специального назначения получает новое важное задание, которое становится для давно уже отошедших от дел спецназовцев единственной возможностью снова увидеть бывших соратников по опасным миссиям. Тем более, что очень важные вопросы их личных взаимоотношений так и остались до конца не решенными. Они так и не приучились называть друг друга по именам, им куда ближе прижившиеся когда-то на службе оперативные псевдонимы, но время и опыт меняют даже тех суперпрофессионалов, что всю жизнь привыкли подчиняться незыблемому и непререкаемому Параграфу. И на сверхсекретной ракетной базе, куда приводит команду высочайший приказ, им придется лицом к лицу столкнуться не только с внешней опасностью, но и друг с другом…",
 "f-wd86684361": "Лучшая саблистка мира, Александра Покровская, знаменита, богата и счастлива. Чтобы войти в историю, ей остаётся сделать последний шаг – взять олимпийское золото. Но путь ей преграждает девятнадцатилетняя Кира Егорова, девушка из провинции, в одночасье покорившая Москву. Кира побеждает на всех соревнованиях и не сходит с обложек глянцевых журналов. Её цель – занять место Покровской. Начинается отчаянная схватка не только на турнирах, но и в жизни. Обе одержимы, и, кажется, остановить их не может ничто.  Весь мир, затаив дыхание, наблюдает за сверканием острых клинков. И всё очевиднее: эта яростная борьба уже зашла слишком далеко...",
 "f-wd124735657": "Чикаго, 1930-е годы. Монстр Франкенштейна просит доктора Юфрониуса помочь создать ему компаньона. Вместе они оживляют убитую девушку, и она превосходит их ожидания.",
 "f-wd847951": "Маньяк по прозвищу «Рикер» ездит по пустыне на своем автомобиле и убивает случайных попутчиков. Останки он кропит в старом разваленном сарае, наполненном ужасным зловонием. Однажды этого сумасшедшего заматывает полицейский Рид, в итоге — убийца попадает на электрический стул.  Спустя много лет, когда шериф Рид готовится сдать свой пост преемнику Харрису в последний рабочий день, трое неудачливых грабителей устраивают взрыв на бензоколонке. Теперь ветерану-полицейскому и его молодому коллеге предстоит разобраться с преступниками и выйти на след еще более зловещей тайны — тайны воскресшего безумца…",
 "f-wd4421364": "Хотели бы вы очутиться в настоящей игрушечной стране, где плюшевый мишка, букварь и МР3‑плеер могут стать вашими друзьями и помогут выбраться из очень опасного приключения? Или побывать ночью в цирке, на необычном представлении, где вы оказались, «следуя за белым кроликом», как героиня другой известной сказки? Или попасть в школу, где вместо уроков вас ждут «страшные приключения» и сказочные монстры? Именно такие истории пришлось пережить героям фильма – самым обычным детям XXI века.",
 "f-wd130393881": "Небогатый землевладелец, живущий на севере Англии в ветшающем поместье \"Грозовой перевал\", однажды подбирает бездомного мальчика и приводит домой. Дочь хозяина Кэтрин называет его Хитклифф, и дети становятся неразлучны. Через несколько лет, когда отец окончательно спускает все деньги, а Кэтрин настаёт пора выходить замуж, девушка хватается за единственный подходящий, по её мнению, вариант - молодого нувориша, который поселился неподалёку. Влюблённый в неё Хитклифф в отчаянии покидает \"Грозовой перевал\", чтобы через несколько лет вернуться в качестве состоятельного господина.",
 "f-wd163899": "В далеком горном племени молодой охотник Д’Лех нашел свою любовь — красотку Эволет. Но когда загадочное воинственное племя напало на деревню и похитило Эволет, Д’Леху ничего не оставалось, как возглавить небольшую группу охотников, чтобы проследовать за этими властелинами войны даже на самый край света, дабы спасти любимую.Ведомому судьбой отряду неумелых воинов предстоит сразиться с саблезубыми тиграми и доисторическими хищниками и в конце героического путешествия найти Потерянную Цивилизацию. Судьба их целиком находится во власти империи, неподдающейся воображению, той, где великие пирамиды простираются до небес. И там они примут бой против могущественного бога, жестко поработившего их народ.",
 "f-wd309545": "В Нюрнберге идет процесс над нацистскими преступниками. Слушаются дела юристов, служивших нацистскому режиму. Напряженная судебная драма сосредоточена вокруг судебного разбирательства под председательством главного судьи, во время которого главный защитник с помощью откровений одного из подсудимых осознает, что он совершает ошибку, выступая в защиту явных пособников нацизма.",
 "f-wd117457809": "Семейство крякв находится в затруднительном положении: пока отец Мак Маллард доволен тем, что его родные всегда будут в безопасности, живя в пруду в Новой Англии, мама Пэм стремится встряхнуть их и показать своим детям — сыну-подростку Даксу и маленькой дочке Гвен — каким большим и многогранным может быть мир.  После того, как семейство мигрирующих уток приземляется на их пруд с захватывающими рассказами о далёких местах, Пэм уговаривает Мака отправиться в семейное путешествие через Нью-Йорк на тропическую Ямайку. Но всё было бы слишком просто, если бы их планам суждено было сбыться.",
 "f-wd4103178": "Школьники Роман и Катя тянутся друг к другу со всей безоглядностью первой любви. Мать Кати очень счастлива во втором браке и в озарении этого счастья хорошо понимает дочь. Роман находит поддержку у отца, давно и безответно любящего Катину маму. Но рядом ходят люди, ничего не знающие о любви...",
 "f-wd107391489": "Охота за золотом империи продолжается. Бесценный жезл, сокровище, которое должно было обеспечить сказочную жизнь в солнечном Рио-да-Жанейро, ускользнуло из цепких рук Ибрагима Бендера и его молодого ученика Остапа и попало к Нестору Махно. Тот уверен: это далеко не единственная драгоценная реликвия, спрятанная в окрестностях. Так красные, белые, бандиты и партизаны ввязываются в гонку за мифическим золотом, и Ося вместе с жуликом-наставником Ибрагимом должен превзойти себя, чтобы не попасться и заполучить жезл. А заодно - вернуть доверие прекраснейшей девушки, которая разочаровалась в Осе и выходит замуж.",
 "f-wd15270573": "История возвышенной неразделенной любви мелкого чиновника к молодой светской даме.",
 "f-wd4329844": "Ровно через 48 часов в Москве прогремит взрыв. Это последняя информация, которую успел передать перед смертью погибший агент. К расследованию подключаются все спецслужбы, но особые надежды возлагают на недавно созданную независимую оперативную группу. В нее входят: юная девушка-хакер, когда-то взломавшая сервер Пентагона; бывший спецназовец, любящий скорость и адреналин; женщина-психолог, чьи внешние достоинства для многих затмевают и ее ум, и ее звание майора; и слепой сапер, которому нюх и интуиция заменяют зрение… И Старший — единственный, сумевший собрать их вместе и научившийся их контролировать. Только эта команда способна, зная КОГДА, вычислить КТО, а главное ГДЕ…",
 "f-wd62350": "Такую экстремальную историю про Смешариков вы не могли себе представить: покинув свою уютную страну, Смешарики оказываются в современном мегаполисе в роли супергероев! Зачем? Они приняли очень важное для себя решение — спасти мир от нависшей угрозы. Этот «ответственный» шаг приводит к самому захватывающему приключению в их жизни!",
 "f-wd135230927": "Секретный агент Аджит Довал выполняет опасную миссию, связанную с геополитическими конфликтами.",
 "f-wd122341144": "История об индийских мигрантах, которые используют маршрут под названием Полёт осла для иммиграции в Канаду и США.",
 "f-wd122909399": "\"Скайфорс\" рассказывает захватывающую историю, вдохновленную реальными событиями, связанными с одним из самых смертоносных авиаударов между Индией и Пакистаном.",
 "f-wd121842080": "Южный Малабар, XVII век. Бывший певец местного правителя направлялся домой, но, после того как его попутчика съела демоница, мужчина заблудился в лесу. Не имея возможности перейти бурную реку, он выходит к некогда богатому запущенному особняку, где его встречают хозяин и единственный слуга. Послушав пение гостя, хозяин предлагает ему остаться на несколько дней, а тот с радостью соглашается, не подозревая, что покинуть зловещий дом будет не так просто.",
 "f-wd122642379": "Мужчина и женщина знакомятся в сочельник, и романтическая ночь превращается в настоящий кошмар.",
 "f-wd64390886": "Еще вчера они были друзьями, напарниками и воевали на одной стороне, а сегодня агент Халид получает приказ уничтожить своего бывшего наставника Кабира, перешедшего на сторону врага. Они знают сильные и слабые стороны друг друга и безошибочно бьют в цель. Цена в их схватке — сама жизнь.",
 "f-wd125422662": "Соседки по квартире Прабха и Ану живут в Мумбае, они образованны и финансово независимы. Однако в глазах общества они — всего лишь женщины. Прабху выдали замуж «вслепую» совсем юной. Ее муж давно уехал на заработки в Европу и не общается с ней. Она очень одинока, но формальное замужество не дает ей возможности наладить личную жизнь. Более юная Ану пытается отказаться от выбранного родителями жениха, ведь у нее уже есть возлюбленный. Но он принадлежит другой касте, а его семья исповедует другую религию.",
 "f-wd20814887": "В керальском селе живёт простой булочник Джозеф вместе с пятилетней дочкой Ниви и помощником Раджендраном. Отец и дочка души друг в друге не чают, им хорошо в своём уютном мирке, куда они никого не пускают. Но однажды стычка с местными хулиганами оборачивается для них неприятностями. Ниточки этой стычки тянутся в прошлое, где у Джозефа всё было другим — имя, работа, семья. Из прошлого в настоящее врывается и враг Джозефа, который по-прежнему жаждет мщения. Герой понимает, что прятаться бессмысленно, и единственный шанс спасти себя и дочь — самому нанести удар.",
 "f-wd96380091": "Викрам сотрудник полиции в департаменте по расследованию преступлений, работает в группе по раскрытию убийств. Он очень умен и сообразителен, и раскрывает дела благодаря своей способности улавливать даже самые мелкие детали. Викрам страдает от посттравматического синдрома из-за проблем в его прошлом и у него регулярно случаются панические атаки, что очень осложняет его работу. У него есть верный напарник - Рохит и любимая девушка - Неха. Викрам уходит в отпуск, но вынужден вернуться, чтобы расследовать новое важное дело.",
 "f-wd1445622": "Приехавшему из Индии много лет тому назад Кишору Лале удается обосноваться на Американской земле и сколотить многомиллионное состояние. Но все годы на чужбине он не забывает о родине. Для того, чтобыпривить сыну любовь к индийской культуре, он решает подобрать ему традиционную индийскую жену. Выбор падает на дочку его старого друга. Замыслы успешно претворяются в жизнь и сын, съездив с братом в Индию, привозит в Америку молодую невесту. Смогут ли молодые люди, выросшие в таким различных социальных условиях, быть счастливы?",
 "f-wd2561440": "1947 год, вырисовываются границы между Индией и Пакистаном. Юная девочка становится свидетелем трагедии, когда её няня оказывается зажатой между любовью двух мужчин и нарастающей волной политического и религиозного насилия.",
 "f-wd1519075": "Наделённый божественным очарованием юноша Радж мечтает подарить свое сердце мистическому ангелу, когда неожиданно встречает девушку Сакину и лишается своего сердца без промедления. Пламя страсти бушует четыре дня и ночи, полностью меняют все его существо. Но внезапно юный мечтатель обнаруживает, что потерял себя в себе самом. Сакина давно любит и любима другим.",
 "f-wd1163010": "Богач Рагху живет за границей в свое удовольствие, совершенно забыв о жене Вайдехи, которая ждет ребенка и страдает от одиночества. После очередной ссоры он отправляет ее обратно в Индию. Чудом выжив в автомобильной катастрофе и узнав о неутешительном диагнозе поставленном врачами, что у него больше не может быть детей, Вайдехи решает убежать от мужа. Рагху бросается в погоню за женой…",
 "f-wd717788": "Субшах Нагре - региональный индийский авторитет. Он, как может, пытается на своей территории сохранить дух справедливости и неприятия зла. Но с ним вступают в открытую конфронтацию арабские мафиози, не получившие согласил на деятельность в его владениях. В центр этого конфликта оказывается вовлечен Шанкар, сын Субхаша, недавно приехавший из Америки. Субхаш, понимая, что началась схватка не на жизнь, а на смерть, уговаривает Шанкара вернуться в Америку, но тот не хочет оставлять отца в трудную минуту...",
 "f-wd746388": "Санджана живет в Сундернагаре с родителями, и ее животными - попугаем Раджей и собакой Джонни. Старшая сестра Рупа живет с мужем в США. Когда Санжане пришло время выходить замуж, Рупа рассказывает о парне, который мог бы ей стать идеальным мужем. Она посылает его в Сундарнагар, чтобы познакомиться с Санжаной и родителями. Прем - полная противоположность Санжаны, но противоположности притягиваются. В его глазах она находит любовь, защиту и обещание долгой счастливой жизни. Для нее это как сбывшийся сон, но ее мечта терпит крах. Проблема в том, что Премом зовут героев и Ритика, и Абхишека, босса Ритика. И, как вы уже очевидно догадались, Прем-жених и Прем-возлюбленный не совпадают и Санджане предстоит сделать выбор...",
 "f-wd6402794": "Фильм - настоящая сага о любви и чести. Он повествует о любви бесстрашного Хана Бадхаша из далекого афганского Кабула к дочери главы одного из свободолюбивых кланов Беназир. На предложение Бадшаха Беназир отвечает согласием только при одном условии: он должен разыскать и привезти голову Хабибуллы - убийцы ее отца. В поисках Хабибуллы Бадшах встречает на своем пути своего дальнего родственника Пашу и Ранбир Сингха - полицейского из Раджпута. Бадшах находит Хабибуллу и убивает его. Ему грозит тюремное заключение в Индии. Он обещает Ранбиру, что вернется в тюрьму только после того, как женится на красавице Беназир. Бадшах сдержал свое слово, вернулся в Индию и сдался властям. Здесь его ожидают пять лет тюрьмы и множество испытаний...",
 "f-wd1500930": "Красавица Пуджа, дочка состоятельных родителей, попадает в автомобильную катастрофу. Жизнь ей спасает Раджа, мечтающий о карьере певца и с этой целью приехавший из Гоа в Мумбаи. Он своевременно доставляет её в больницу, но она впадает в кому, и жизнь ее находится в опасности. Познакомившиеся с Раджой родители Пуджи принимают его за мужа своей дочери, а он не торопится разуверять их, так как надеется, что они смогут помочь ему стать популярным певцом. Вскоре приезжает Джанви, ближайшая подруга Пуджи. Раджа влюбляется в неё, и она отвечает ему взаимностью. К всеобщей радости Пуджа выходит из комы, но, выздоровев, она начинает оказывать внимание Радже...",
 "f-wd20814436": "Фрида занимается коммерческой съёмкой для модной индустрии и пытается найти собственный путь в искусстве. Она собирает подруг со всей Индии в Гоа, чтобы объявить им неожиданную новость: скоро будет её свадьба! Так начинается импровизированный девичник, который длится целую неделю – бесшабашное путешествие со взлётами и падениями в роскошных декорациях. Веселье и паника, разбитые сердца и душевные раны, страсть и одержимость открывают двери к тайнам и закаляют дружбу, а эмоции бьют ключом. Скоро события приобретут более серьёзный оборот, но пока молодые женщины намерены взять от жизни всё.",
 "f-wd1061749": "Комедия-боевик о простом поваре из Чандни Чоук, ошибочно принятом за реинкарнацию древнего воина Лиу Шенга посетителями из постоянно притесняемой китайской деревни.",
 "f-wd6314288": "Фильм основан на исторических событиях, связанных с антиколониалистским народным восстанием в Индии 1857-1859 гг., известным как восстание сипаев. Солдаты Ост-Индской Компании взбунтовались против использования патронов, пропитанных свиным и коровьим жиром, что оскорбляло религиозные чувства индусов и мусульман. К восставшим присоединилось множество мелких княжеств в надежде освободить свои территории от англичан. Действие фильма происходит в небольшом городке. Часть элиты мусульманской общины, во главе с Сарфараз Ханом, восстала против своих британских хозяев. Трое женщин из семьи лорда Лабадура нашли убежище у местного ростовщика Лала Рамджимала..",
 "f-wd949228": "Полицейскому управлению удалось напасть на след банды и схватить самого главаря — Габбар Синха. Но ни в одной камере нет таких стен, которые могли бы удержать его. Преступник бежит из тюрьмы и жестоко расправляется с семьей инспектора полиции.  Чтобы отомстить кровавому насильнику и защитить мирную деревню от банды разбойников, инспектор Тхакур нанимает двоих смельчаков. У него свой счет к главарю банды, но месть смирится перед законом…",
 "f-wd108858400": "Алекс Клермонт-Диас, сын президента США, и британский принц Генри имеют много общего, но относятся друг к другу с абсолютным презрением. После публичного конфликта, чтобы избежать негативных последствий для своих стран, парням приходится делать вид, что у них хорошие отношения. Постепенно их вынужденная дружба перерастает в нечто большее.",
 "f-wd132407629": "История жениха и невесты, чья первая брачная ночь внезапно прерывается бандой головорезов, охотящихся за таинственным человеком по имени «Чарли».",
 "f-wd134520410": "Семья среднего класса борется с финансовыми трудностями и неудачами в личной жизни, стремясь к своей мечте — собственной квартире в большом городе.",
 "f-wd39048745": "События кинокартины разворачиваются в середине 20 века, талантливо и чувственно передавая дух того времени. Актриса Савитри стала жемчужиной киноиндустрии, она была известна своей красотой и выдающимися актерскими способностями. Савитри стала величайшей женщиной Индии, которая достигла равных высот с мужчинами суперзвездами, благодаря своему трудолюбию, желанию полностью отдаваться работе и таланту искусно вести дела. Многие события жизни Савитри кажутся невероятными, однако, это то, с чем ей пришлось столкнуться на своем пути к славе.",
 "f-wd536299": "Синь, бывший мастер боевых искусств, после смерти своего учителя собирает команду из своих братьев и друзей, чтобы объединить кунг-фу и футбол. Вместе они решают принять участие в крупном футбольном турнире, где их необычные навыки становятся главным преимуществом. На пути к финалу команде предстоит столкнуться с сильными соперниками, преодолеть старые разногласия и доказать, что настоящая сила заключается не только в мастерстве, но и в дружбе.",
 "f-wd478780": "В поисках интересного персонажа для статьи журналист Марко встречается со знаменитой женщиной-тореро Лидией. Их знакомство перерастает в страстную любовь, но все надежды рушит трагедия на корриде: удар разъяренного быка повергает Лидию в кому. Проводя дни и ночи в больнице, Марко знакомится с медбратом Бениньо. Он не первый год заботится о впавшей в кому Алисии, которую страстно любит, не надеясь на взаимность.",
 "f-wd2991452": "Индийский спецагент по прозвищу Тигр во время очередной миссии влюбляется в очаровательную танцовщицу Зою — помощницу ученого, который подозревается в продаже секретных технологий пакистанской разведке.",
 "f-wd262778": "Отец и сын Датт — играют отца и сына. Отец — обычный крестьянин Хари Прасад Шарма, как и миллионы отцов, жертвующий всем ради сына. Он мечтает о том, чтобы Мунна (его сын) стал доктором и лечил бы всех людей. Для этого он отправляет Мунну в город и намерен оплатить его учебу.  Но судьба приводит Мунну в страшный преступный мир и он становится бомбейским доном, бесчестным королем бандитов. Но Мунна понимает, что сердце отца разобьется, если он узнает о профессии сына. Чтобы избежать этого, он лжет отцу, что его мечта сбылась и он стал доктором. Но ему удается без труда обманывать отца до того дня, когда отец решает навестить сына в городе. Для так называемого «доктора» это неожиданная ситуация, но это вызов его хитрости.  Так братан Мунна изображает перед отцом доброго доктора, и чтобы убедить его, открывает бесплатную больницу для всех неимущих. Но отец всегда умнее, чем думает его ребенок. С каждым днем Мунне все труднее обманывать отца…",
 "f-wd21647697": "12-летний Майк вместе со своими друзьями пытается спасти Луну от захвата злобным миллиардером Карсоном. Но для этого надо всего лишь… полететь в космос. Удастся ли обыкновенным подросткам пробраться на космическую базу, прилуниться и победить коварного злодея? Для этого понадобится помощь друзей, верной домашней ящерицы и родного деда. Большое космическое приключение, объединившее всю семью, начинается!",
 "f-wd565130": "Мужчина, семь лет назад потерявший жену, решает найти себе подругу жизни. С помощью приятеля из шоу-бизнеса он организовывает кинопробы, которые становятся смотринами девушек разных возрастов и их вредных привычек.",
 "f-wd489818": "Весь день Тэ-сук разъезжает на мотоцикле по городу, развешивая на дверях домов рекламные плакаты. А вечером он сорвет плакат с того дома, где отсутствует хозяин, и временно пропишется в его квартире.  Тэ-сук моет посуду, стирает белье и чинит вещи. В одном из домов он не замечает странную молчаливую женщину. Сун-хва давно несчастлива в браке, страдает от побоев мужа и, улучив момент, бежит с Тэ-суком, принимая его образ жизни и меняя одну квартиру за другой, один дом за другим…",
 "f-wd600176": "С твердой решимостью создать здоровую семью 23-летний экс-пациент психушки Рикки похищает киноактрису-наркоманку Марину, причем в последний день съемок.  От полноты чувств и ввиду явного сопротивления он ее малость тискает и крепко привязывает к кровати. Грубое насилие приносит неожиданно щедрые плоды в виде ответного чувства Марины к своему как бы мучителю.",
 "f-wd478076": "Сюжет построен вокруг убийства на почве страсти. То, что это любовь гомосексуалистов, сути не меняет. Любовь сводит людей с ума и толкает на преступление, оставаясь неподсудной. Молодой любовник известного кинорежиссера убивает соперника — полиция ведет следствие…",
 "f-wd1261372": "Знаменитый «пьяный мастер» возвращается домой после поездки, когда ему в руки случайно попадает древняя имперская печать, которую англичане хотят вывезти из Китая. Лишь его мастерство может защитить реликвию, но его отец против того, чтобы сын занимался этим опасным стилем боя.",
 "f-wd225175": "Китай времён динacтии Цин. Бедный сирота Цзянь Фу случайно спасает жизнь мастеру кунг-фу Бай Чжантяню, последнему оставшемуся в живых представителю школы Змеиного Кулака, уничтоженной зловещим кланом Орлиного Когтя. Благородный мастер берёт юношу в ученики, дабы передать ему секреты своего боевого стиля. А ученик оказывается настолько талантлив, что на основе приёмов учителя даже создаёт собственный стиль. Очень своевременное изобретение, которому вскоре придётся пройти самую суровую проверку, когда орда адептов Орлиного Когтя во главе с непобедимым Шангуань Июнем обнаружат Бай Чжантяня и явятся убить его.",
 "f-wd748412": "Астерикс и Обеликс получают от своего вождя необычное задание: они должны воспитать настоящим воином его племянника, Простопникса. Юноша оказывается слабаком, пацифистом и трусом, совершенно неспособным быть воином и «настоящим мужчиной». Его больше прельщают танцы и развлечения. Он всячески увиливает от занятий, боится всего и не способен справиться даже с слабейшим противником.",
 "f-wd1543027": "Действие картины начинается в конце Второй мировой войны. Преподаватель военной академии Утидо уходит в отставку и живет с женой в скромном домишке какого-то разрушенного имения, где его постоянно навещают преданные ученики — помогают ему, справляют каждый год день его рождения, организуют поиски пропавшей кошки, пропажа которой является самым волнующим событием за те 15 лет, которые вмещает действие фильма.",
 "f-wd612298": "Четверо братьев и сестер живут с матерью в маленькой квартирке в Токио. У всех детей разные отцы, они никогда не ходили в школу, а сам факт существования троих из них скрывается от домовладельца. Однажды мать уходит, оставив немного денег и записку, в которой просит 12-летнего сына присмотреть за остальными.",
 "f-wd316761": "У Франка, профессионального «пушера» — так называют мелких уличных торговцев наркотиками — крупные неприятности. Он должен 50 тыс. своим поставщикам-югославам, а вдобавок к этому во время продажи героина приезжим шведам налетела полиция, и весь товар, взятый в долг, пришлось выбросить в пруд.  Друг Тонни, с кем они вместе работали, во всем признался полиции. Но товар выброшен, улик нет, и Франка выпустили. Теперь его долг поставщику Мило — 180 тыс.  Франк любит проститутку Вик, красивую девушку, но безнадежную наркоманку. Кроме нее, пожалуй, ничего хорошего в жизни Франка и нет. И денег нет, а Мило требует вернуть долг. Не сможет — вышибала Мило Радован вырежет ему ножом коленные чашечки. Франк покупает пистолет. Поставщики тем временем узнают, что он дерзнул открыть собственное дело. Такое не прощается…",
 "f-wd1155695": "Основатель старейшей Школы боевых искусств намерен уйти на покой и передать дела достойному преемнику. Но самый лучший его ученик вынашивает куда более амбициозные планы - он намерен объединить все разрозненные школы в одну. С этой целью он вызывает на поединок лидера каждой школы и, одерживая победу раз за разом, объединяет все школы. Последней остается школа его умершего учителя, отстоять память которого на поединок выходит его дочь, тайно влюбленная в своего соперника",
 "f-wd255260": "Две сестры возвращаются в дом своего отца и мачехи после продолжительного пребывания в психиатрической лечебнице. Ситуация в доме носит напряженный характер, так как состояние мачехи весьма несбалансированное. Вскоре в доме начинают происходить странные вещи, сёстрам кажется, что внутри есть кто-то еще…",
 "f-wd119786383": "Сидя вечером у телевизора в своей квартире на Манхэттене, пес и не подозревал, что после покупки друга-робота по объявлению, в его жизнь ворвутся приключения, которые раз и навсегда изменяет его жизнь.",
 "f-wd72162": "Аргентина, 1979 год. После многих лет изгнания Хуан и его семья возвращаются в Аргентину под чужими именами. Родители Хуана и его дядя Бето — члены Организации Монтонерос, которая борется против военной хунты, правящей страной. Из-за своей деятельности они живут под постоянной угрозой ареста и даже смерти. Однако повседневная жизнь Хуана также полна тепла и юмора, и он быстро и легко привыкает к своей новой среде. Его друзья в школе и Мария, девочка, которая ему очень нравится, знают его как Эрнесто — и он должен жить под этим именем ради выживания своей семьи. Хуан принимает это и выполняет все правила своих родителей, пока однажды они не говорят ему, что им немедленно нужно переехать в другое место, и он должен будет оставить Марию и друзей без каких-либо объяснений…",
 "f-wd387727": "Подвыпившая толстушка рыдает и кричит, что ее никто не любит, а друг пытается ее успокоить. Молодая фанатка рок-н-ролла влюблена в гитариста группы, но для него она - лишь одна из поклонниц. Музыканты репетируют в своих квартирах, не обращая внимания на близких и соседей. Пожилой психиатр признается, что давно не лечит людей, а просто выписывает им сильнодействующие лекарства. Водителю бетономешалки снится сон, будто его казнят на электрическом стуле за \"жестокое обращение с чужой собственностью\". Жизнь идет своим чередом...",
 "f-wd1444720": "К 1999 году все гигантские земные монстры (в том числе и Годзилла) оказались пойманы и отправлены на небольшой японский островок для заточения и изучения. Однако группа инопланетян сумела подчинить себе чудовищ, освободить их и вновь направить против человечества. Команде астронавтов поручено в срочном порядке найти и ликвидировать базу злобных пришельцев, пока контролируемые ими монстры не сравняли с землёй все города планеты.",
 "f-wd391544": "Шири / Swiri / Shiri / 쉬리  - это крошечная пресноводная рыбка, которая водится в чистейших корейских реках. Это маленькое, непокорное существо предпочитает мелким и спокойным водоемам дикие и каменистые быстрины. «Шири» - так называется тайная террористическая операция, на выполнение которой отправляются секретные агенты восьмого специального отдела северокорейских вооруженных сил. Элитные сотрудники восьмого отдела не знают, что такое сомнения и страх. Эти люди - одержимые самоубийцы, которых никто и ничто не остановит. Зловещий восьмой отдел уже давно заслал одного из своих лучших агентов по имени Хи в миролюбивую и преуспевающую, а посему враждебную и ненавистную Южную Корею. Хи - профессиональный снайпер, отправивший на тот свет вереницу правительственных чиновников и каждый раз исчезавший без следа. Теперь перед двумя лучшими агентами южнокорейского комитета госбезопасности стоит чрезвычайно опасная задача: обезвредить снайпера-убийцу Хи и сорвать ужасную операцию «Шири».",
 "f-wd735047": "Романтическая драма о возвышенной первой любви двух подростков-идеалистов и противоречии с миром взрослых, погрязших в ежедневных проблемах и разуверившихся в жизни. Он подрабатывает в гараже помощником механика и ездит на мопеде. Она ничего не делает, только красит губы. Они курят до посинения и боятся заговорить друг с другом. Но, пройдя через мордобой, слезы и первое похмелье, они все-таки доберутся до конца фильма вместе.",
 "f-wd23838435": "У финского боксера Олли Мяки есть все шансы завоевать титул чемпиона мира в полулёгком весе. Он уже преодолел все неудачи, теперь спортсмену из провинциальной глубинки пророчат славу и богатство. Дело за малым: остается сконцентрироваться на решающем поединке, но на пути к триумфу появляется новое испытание — девушка. Олли Мяки всё же станет легендой спорта, но не благодаря победе.",
 "f-wd64854696": "Историческая военная драма, рассказывающая о четырехдневной обороне склада Сихан в Шанхае 1937 года во время битвы за Шанхай. Неравная битва 524-го полка 88-й дивизии, в которой осталось в живых меньше половины из восьми сотен бойцов (вошедших в историю как «Восемьсот храбрецов»), против 20 тысяч солдат японской армии. Склад не был стратегически важен, однако героическое сопротивление должно было поднять боевой дух китайского народа после ряда поражений и помочь заручиться поддержкой иностранных союзников, которые наблюдали за битвой с другой стороны реки Сучжоу.",
 "f-wd75682": "На Наруто возложена миссия захватить Мукаде (Мукаде был одним из шпионов Сасори) пропавшего без вести. Наруто Узумаки отправляется к руинам долины «Оурен» и находит там Мукаде. Цель Мукаде — найти источник некой силы, что дремлет в этих руинах. Мукаде пытается воспользоваться этой силой и по не осторожности мощный луч света охватывает Наруто и отправляет его в прошлое, на 20 лет назад. Когда Наруто просыпается, он встречает четвертого Хокаге Минато Намиказе.",
 "f-wd494306": "Меннониты, в общине которых происходит действие фильма, поселились в северной Мексике в конце позапрошлого века, но поскольку их религия запрещает браки с иноверцами, им удалось сохранить этническую чистоту и абсолютную культурную обособленность. Герой картины образцовый муж и отец многодетной семьи, влюбляется в хозяйку кафе Марианну. На плечи набожного Йохана сваливается непосильный груз моральной дилеммы. Любовь к Марианне становится полем битвы божественного и дьявольского.",
 "f-wd115890": "Мать переезжает со своими дочерьми в большой загородный дом. Старшая дочь страдает от болезни легких, и ее врач посоветовал их семье переехать в пригород. Дом им предоставляет Джи-Тай, отец которого работал вместе с умершим отцом их семьи.  В то время как семья пытается приспособиться к новой обстановке, старшая дочь делает удивительное открытие. В запертой комнате в сарае живет дикий юноша. Семья принимает его, считая, что он просто сирота с плохо развитыми навыками общения. Он же начинает проявлять интерес к старшей дочери. Между тем, Джи-Тай имеет свои планы жениться на ней. В чем же секрет одичалого юноши?",
 "f-wd8564063": "В городе появляется новый вирус, который передается через дыхательные пути и убивает в течение 36 часов после инфицирования.",
 "f-wd487492": "Корея под японской оккупацией. Ким Джун-щик мечтал стать следующим Сон Ги-джоном (корейский марафонец, который выиграл олимпийское золото в период японского колониального господства), чтобы соперничать с лучшим японским чемпионом Хасэга Тацуо. Джун-щик не хотел идти на войну, а Тацуо был горд служить своей стране. Оба были вынуждены вступить в армию.",
 "f-wd1465323": "Высоко на скале в середине огромного леса стояла большая крепость. В той крепости жила банда разбойников, которые грабили невинных людей, которые проезжали через лес. Предводителем банды был Маттис. Однажды ночью случилась ужасная гроза. Огромная молния ударила в скалу и разделила ее и крепость надвое. В ту же ночь в крепости родилось двое детей — у Маттиса родилась дочь, а у Борки, ставшего предводителем второй части банды, которая поделилась надвое, как и крепость, родился сын. С тех пор между двумя бандами была вражда. Казалось, ничего не могло соединить их снова, но есть две вещи, которые преодолевают все обстоятельства — любовь и дружба. Дети росли, и однажды отправились в путешествие в лес. Путешествие предстояло нелегким, в пути их ждали фантастические приключения, странные и опасные существа и новые друзья…",
 "f-wd947446": "Конец прошлого столетия. Китайцы пытаются бороться всеми доступными им средствами с расширением американского влияния, решительно восстают против наглого грабежа и похищения людей.  Но находятся и такие, которым чужестранная мода, традиции и культура пришлись на руку в их темных делишках. Народный герой Китая Вонг пытается защитить девушку, которую предприимчивый барыга — китаец продал на Запад в бордель.",
 "f-wd1393064": "Северокореец Кунам (Ха Джунву) работает таксистом в Китае. Он должен «чосонской» мафии крупную сумму денег за южнокорейскую визу для его жены. Выплатить этот долг в обозримом будущем представляется нереальным, поэтому он вынужден терпеть издевательства бандитов. Кроме того, уже долгое время нет никаких вестей от уехавшей в Сеул жены. Поэтому, когда главарь банды Мюнга (Ким Юнсок) предлагает ему дать недостающую сумму в обмен за убийство одного человека в южнокорейской столице, Кунам соглашается и отправляется нелегалом в Южную Корею.",
 "f-wd1091180": "После 15 лет замужества Давид и Марианна расходятся. Однако случайное совместное путешествие в поезде выливается в выяснение отношений,  которое приводит к взаимопониманию супругов…",
 "f-wd27703164": "Опытный агент спецназа борется чтобы защитить молодую женщину от зловещей организации. Одновременно он чувствует особую связь с этой женщиной, как будто они уже встречались в другой жизни.",
 "f-wd495637": "Февраль 1953 года. Корейская война близится к концу. Cтороны ведут переговоры о прекращении огня и заключении перемирия, но переговорный процесс идет не так легко. В то же время их армии все еще продолжают сражаться. Особенно ожесточенные бои идут на восточном фронте в районе холма Эрок.",
 "f-wd110833192": "Ракель уже давно тайно влюблена в своего соседа. Но все меняется, когда он начинает отвечать ей взаимностью несмотря на протесты родителей.",
 "f-wd116005474": "Египетские мумии живут под землей в секретном городе, который является точным отражением Древнего Египта времен фараонов. Три мумии — принцесса, бывший возничий и его младший брат вместе со своим домашним крокодилом попадают в забавное приключение, в ходе которого они случайно попадают в современный Лондон, где попытаются найти древнее кольцо, украденное археологом, лордом Карнаби.",
 "f-wd718536": "По сюжету Наруто сажают в тюрьму под названием «Кровавая тюрьма» за покушение на убийство Райкагэ и убийство нескольких синоби, и Наруто пытается доказать свою невиновность.",
 "f-wd484291": "Три страшные истории. Кёко — знаменитая писательница и красивая женщина, но ведет одинокий образ жизни. Когда она была ребёнком, с ней случилось что-то страшное.  Ни одна женщина не сможет устоять, если ей представится возможность омолодиться, а Цин может себе это позволить. Бывшая звезда телевидения вышла замуж за знаменитого богача и обречена на то, чтобы ее мечта сбылась. Она знакомится с таинственным поваром Мей, которая готовит ей пельмени по особому рецепту.  Рю Цзи-хо — преуспевающий кинорежиссер — богатый, уважаемый, талантливый, симпатичный и красивый. Вернувшись однажды домой, он обнаруживает там совершенно незнакомого человека. Этот незнакомец — актер массовки, на которого Рю никогда не обращал внимания.",
 "f-wd933674": "Сатана был проклят Богом на вечное творение зла – и за каждого поддавшегося искушению смертного, муки Сатаны продлеваются на сто лет, а за каждого удержавшегося от искушения сокращаются на тысячу. Четыре истории рассказывают о том, как Сатана исполняет свой долг.",
 "f-wd10425783": "В мультфильме «Медвежонок Бамси и Город Разбойников» самый сильный медведь в мире и два его друга Литтл Хопп и Шеллман показывают, что лучшее оружие против зла - дружба (и, конечно, несколько капель бабушкиного громового меда).",
 "f-wd27842209": "Жизнь беспечного бигля Оззи переворачивается с лап на голову, когда, отправляясь в отпуск, семья Мартинов отдает его в элитный спа-отель для собак. Но хозяева не могли и представить, что это всего лишь ловушка, а их любимец окажется в настоящей собачьей тюрьме. Чтобы прорваться через супер-систему охраны и злющих сторожевых псов, Оззи вместе с такими же бедолагами, как он, должен будет спланировать самый хитроумный и дерзкий побег в истории."
};
